def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find connected components of non-background, non-5 cells.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (0, 5) or (r, c) in seen:
                continue
            comp = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            grid[yy][xx] not in (0, 5) and
                            (yy, xx) not in seen):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            comps.append(comp)

    # Find contiguous horizontal and vertical 5-lines.
    runs = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == 5 and (c == 0 or grid[r][c - 1] != 5):
                end = c
                while end + 1 < w and grid[r][end + 1] == 5:
                    end += 1
                if end > c:
                    runs.append(("H", r, c, end))
                c = end + 1
            else:
                c += 1

    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == 5 and (r == 0 or grid[r - 1][c] != 5):
                end = r
                while end + 1 < h and grid[end + 1][c] == 5:
                    end += 1
                if end > r:
                    runs.append(("V", c, r, end))
                r = end + 1
            else:
                r += 1

    for orient, fixed, start, end in runs:
        for comp in comps:
            minr = min(y for y, x in comp)
            maxr = max(y for y, x in comp)
            minc = min(x for y, x in comp)
            maxc = max(x for y, x in comp)

            if orient == "H":
                # A vertical color strip at either endpoint extends across the 5-line.
                anchor = start if minc == maxc == start else end if minc == maxc == end else None
                if anchor is None:
                    continue
                if any((fixed + 1, anchor) == p or (fixed - 1, anchor) == p for p in comp):
                    for c in range(start, end + 1):
                        for r in range(minr, maxr + 1):
                            if (r, anchor) in comp:
                                out[r][c] = grid[r][anchor]

            else:
                # A horizontal strip, or a multi-row tile, repeats along the 5-line.
                side = minc if minc > fixed else maxc if maxc < fixed else None
                if side is None:
                    continue
                if not any(abs(x - fixed) == 1 for y, x in comp):
                    continue
                for r in range(start, end + 1):
                    source_r = minr + ((r - minr) % (maxr - minr + 1))
                    for c in range(minc, maxc + 1):
                        if (source_r, c) in comp:
                            out[r][c] = grid[source_r][c]

    return out
